<?php
require __DIR__.'/config.php';require __DIR__.'/theme-loader.php';$theme=loadTheme();$db=getDb();
function publicChallengeEscape($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function publicChallengeDateTime(?string $value):string{if(!$value)return '';try{return (new DateTimeImmutable($value,new DateTimeZone('America/Denver')))->setTimezone(new DateTimeZone('America/Denver'))->format('M j, Y \\a\\t g:i A T');}catch(Throwable $e){return '';}}
function publicChallengeTimestamp(?string $value):string{if(!$value)return '';try{return (string)(new DateTimeImmutable($value,new DateTimeZone('America/Denver')))->getTimestamp();}catch(Throwable $e){return '';}}
$challenges=$db->query("SELECT * FROM challenges WHERE status IN ('published','closed') ORDER BY COALESCE(starts_at,created_at) DESC,id DESC")->fetchAll(PDO::FETCH_ASSOC);
$submissions=[];$awards=[];
foreach($challenges as $c){$id=(int)$c['id'];$s=$db->prepare("SELECT s.*,q.name squadron_name FROM challenge_submissions s LEFT JOIN squadrons q ON q.id=s.squadron_id WHERE s.challenge_id=? AND s.status='published' ORDER BY s.created_at");$s->execute([$id]);$submissions[$id]=$s->fetchAll(PDO::FETCH_ASSOC);$s=$db->prepare("SELECT * FROM engagement_awards WHERE challenge_id=? AND status='published' ORDER BY created_at DESC,id DESC");$s->execute([$id]);$awards[$id]=$s->fetchAll(PDO::FETCH_ASSOC);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="<?php echo publicChallengeEscape($theme['primary_color']);?>"><title>Group Challenges | GroupStatistics</title><link rel="stylesheet" href="site-ui.css"><link rel="stylesheet" href="site-components.css"><style>:root{--primary:<?php echo publicChallengeEscape($theme['primary_color']);?>;--page:<?php echo publicChallengeEscape($theme['background_color']);?>;--ink:<?php echo publicChallengeEscape($theme['text_color']);?>}body{margin:0;background:var(--page);color:var(--ink);font:16px/1.55 Arial}.hero{background:var(--primary);color:white;padding:28px 18px}.hero-in,main{max-width:1050px;margin:auto}.hero h1{margin:0}.wrap{padding:24px 14px 50px}.challenge{background:white;border:1px solid #dbe3ed;border-radius:13px;padding:22px;margin-bottom:18px}.challenge h2{color:var(--primary);margin:0}.meta{color:#64748b;font-size:.88rem}.desc{white-space:pre-line}.entry{border-top:1px solid #e2e8f0;padding:12px 0}.pill{display:inline-block;background:#e8eef6;color:#002147;border-radius:99px;padding:5px 9px;margin:4px;font-size:.85rem;font-weight:bold}.challenge-countdown{display:inline-block;margin:8px 0 12px;padding:10px 14px;border-radius:9px;background:#e8eef6;border:1px solid #cbd5e1;color:#002147;font-weight:800;font-size:1.2rem;font-variant-numeric:tabular-nums}.challenge-countdown.is-active{background:#e8f7ee;border-color:#8ac6a0;color:#17633b}.challenge-countdown.is-ended{background:#f1f5f9;color:#64748b}.award{background:#f8fafc;border-left:4px solid var(--primary);padding:12px;margin:10px 0}.empty{padding:30px;background:white;border:1px dashed #cbd5e1;border-radius:12px;text-align:center;color:#64748b}@media(max-width:520px){.challenge{padding:15px}}</style></head><body><?php require_once __DIR__.'/site-header.php';renderGroupSiteHeader();?><header class="hero"><div class="hero-in"><h1>🎯 Group Challenges</h1><p>Current challenges, posted submissions, and challenge awards.</p></div></header><main class="wrap">
<?php if(!$challenges):?><div class="empty">No challenges have been published yet.</div><?php endif;?>
<?php foreach($challenges as $c):$id=(int)$c['id'];?><article class="challenge" id="challenge-<?php echo $id;?>"><h2><?php echo publicChallengeEscape($c['title']);?></h2><p class="meta"><?php if(!empty($c['starts_at'])):?>Starts <?php echo publicChallengeEscape(publicChallengeDateTime($c['starts_at']));?><?php else:?>Start time not set<?php endif;?><?php if(!empty($c['ends_at'])):?> · Ends <?php echo publicChallengeEscape(publicChallengeDateTime($c['ends_at']));?><?php endif;?> · <?php echo $c['status']==='closed'?'Closed':'Published';?></p><?php if(!empty($c['starts_at'])):?><div class="challenge-countdown" data-challenge-countdown data-start-target="<?php echo publicChallengeEscape(publicChallengeTimestamp($c['starts_at']));?>" data-end-target="<?php echo publicChallengeEscape(publicChallengeTimestamp($c['ends_at']??null));?>" data-challenge-status="<?php echo publicChallengeEscape($c['status']);?>">Loading countdown…</div><?php endif;?><p class="desc"><?php echo nl2br(publicChallengeEscape($c['description']));?></p><?php if($c['instructions']):?><h3>Instructions / criteria</h3><p class="desc"><?php echo nl2br(publicChallengeEscape($c['instructions']));?></p><?php endif;?>
<h3>Submissions</h3><?php if(!$submissions[$id]):?><p class="meta">No submissions have been posted yet.</p><?php endif;?><?php foreach($submissions[$id] as $s):?><div class="entry"><strong><?php echo publicChallengeEscape($s['title']);?></strong><?php if($s['squadron_name']):?><span class="pill"><?php echo publicChallengeEscape($s['squadron_name']);?></span><?php endif;?><?php if($s['submitter_label']):?><span class="meta"> · <?php echo publicChallengeEscape($s['submitter_label']);?></span><?php endif;?><p class="desc"><?php echo nl2br(publicChallengeEscape($s['description']));?></p><?php if($s['source_url']):?><a href="<?php echo publicChallengeEscape($s['source_url']);?>" target="_blank" rel="noopener noreferrer">View original submission ↗</a><?php endif;?></div><?php endforeach;?>
<h3>Challenge awards</h3><?php if(!$awards[$id]):?><p class="meta">Awards have not been announced yet.</p><?php endif;?><?php foreach($awards[$id] as $a):?><div class="award"><strong>🏅 <?php echo publicChallengeEscape($a['title']);?></strong><p class="desc"><?php echo nl2br(publicChallengeEscape($a['description']));?></p><?php if(in_array($a['award_type'],['points','both'],true)):?><b><?php echo publicChallengeEscape($a['points_awarded']);?> points per recipient squadron</b><?php endif;?><?php $ar=$db->prepare('SELECT q.name,r.points_awarded FROM engagement_award_recipients r JOIN squadrons q ON q.id=r.squadron_id WHERE r.award_id=? ORDER BY q.id');$ar->execute([(int)$a['id']]);$awardRecipients=$ar->fetchAll(PDO::FETCH_ASSOC);if($awardRecipients):?><p><?php foreach($awardRecipients as $recipient):?><span class="pill"><?php echo publicChallengeEscape($recipient['name']);?><?php if($recipient['points_awarded']!==null):?> · <?php echo publicChallengeEscape($recipient['points_awarded']);?> pts<?php endif;?></span><?php endforeach;?></p><?php endif;?></div><?php endforeach;?></article><?php endforeach;?>
</main><script>(function(){var timers=[].slice.call(document.querySelectorAll("[data-challenge-countdown]"));function update(){var now=Math.floor(Date.now()/1000);timers.forEach(function(el){var start=Number(el.dataset.startTarget||0),end=Number(el.dataset.endTarget||0),status=el.dataset.challengeStatus;el.classList.remove("is-active","is-ended");if(status==="closed"){el.textContent="Challenge closed";el.classList.add("is-ended");return;}if(start&&now<start){var left=start-now,days=Math.floor(left/86400),hours=Math.floor(left%86400/3600),minutes=Math.floor(left%3600/60),seconds=left%60;el.textContent="Starts in "+(days?days+"d ":"")+[hours,minutes,seconds].map(function(n){return String(n).padStart(2,"0");}).join(":");return;}if(end&&now>=end){el.textContent="Challenge ended";el.classList.add("is-ended");return;}el.textContent="Challenge in progress";el.classList.add("is-active");});}update();if(timers.length)window.setInterval(update,1000);})();</script></body></html>
